local Sawmill = {}
local PRODUCTS = {
    pine_plank = { name = "Borova deska", pineLogCost = 1, time = 1, cost = 10, quality = 30, description = "Borova deska za vsakdanjo rabo." },
    oak_plank = { name = "Hrastova deska", oakLogCost = 1, time = 2, cost = 25, quality = 50, prestige = 1, description = "Hrastova deska za gradnjo." },
    ash_plank = { name = "Jesenova deska", ashLogCost = 1, time = 2, cost = 38, quality = 65, prestige = 2, description = "Jesenova deska za pohištvo." },
    yew_plank = { name = "Tisova deska", yewLogCost = 1, time = 3, cost = 90, quality = 80, prestige = 5, happiness = 1, description = "Tisova deska za fine izdelke." },
    ebony_board = { name = "Ebenova tabla", ebonyLogCost = 1, time = 5, cost = 240, quality = 92, prestige = 12, happiness = 2, description = "Ebenova tabla za luksuzno pohištvo." },
    royal_grand_board = { name = "Kraljevski veliki tabla", ebonyLogCost = 1, yewLogCost = 1, goldCost = 1, jewelCost = 1, time = 9, cost = 1000, quality = 100, prestige = 32, happiness = 7, description = "Velika kraljevska tabla z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Žagarska delavnica", cost = { gold = 250, wood = 130, stone = 100 }, upkeep = 6, qualityBonus = 5 },
    water_sawmill = { name = "Vodna žaga", cost = { gold = 900, wood = 250, stone = 400, iron = 6 }, upkeep = 22, qualityBonus = 18 },
    blade_house = { name = "Listna hiša", cost = { gold = 2200, wood = 350, stone = 600, silver = 25, steel = 8 }, upkeep = 55, qualityBonus = 30 },
    royal_sawmill_atelier = { name = "Kraljevski atelje žage", cost = { gold = 9000, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
Sawmill.pineLogStock = 18; Sawmill.oakLogStock = 16; Sawmill.ashLogStock = 12; Sawmill.yewLogStock = 10; Sawmill.ebonyLogStock = 6; Sawmill.goldStock = 6; Sawmill.jewelStock = 6
Sawmill.productStock = {}; Sawmill.buildings = {}; Sawmill.maker = nil; Sawmill.activeMaking = {}; Sawmill.totalProducts = 0; Sawmill.dayTimer = 0
function Sawmill.init() Sawmill.pineLogStock=18; Sawmill.oakLogStock=16; Sawmill.ashLogStock=12; Sawmill.yewLogStock=10; Sawmill.ebonyLogStock=6; Sawmill.goldStock=6; Sawmill.jewelStock=6; Sawmill.productStock={}; Sawmill.buildings={}; Sawmill.maker=nil; Sawmill.activeMaking={}; Sawmill.totalProducts=0; Sawmill.dayTimer=0; print("[Sawmill] Royal Sawmill System initialized (6 products, 4 buildings)") end
function Sawmill.hireMaker(n,s) s=s or math.random(50,90); local c=480+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; Sawmill.maker={name=n or ("Žagar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žagar najet: %s (spretnost: %d)",Sawmill.maker.name,s),"success") end; return true end
function Sawmill.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function Sawmill.build(id) local ok,e=Sawmill.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(Sawmill.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function Sawmill.getQualityBonus() local b=0; for _,bd in ipairs(Sawmill.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function Sawmill.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.pineLogCost and Sawmill.pineLogStock<(d.pineLogCost or 0) then return false,"Premalo borovih hlodov" end; if d.oakLogCost and Sawmill.oakLogStock<(d.oakLogCost or 0) then return false,"Premalo hrastovih hlodov" end; if d.ashLogCost and Sawmill.ashLogStock<(d.ashLogCost or 0) then return false,"Premalo jesenovih hlodov" end; if d.yewLogCost and Sawmill.yewLogStock<(d.yewLogCost or 0) then return false,"Premalo tisovih hlodov" end; if d.ebonyLogCost and Sawmill.ebonyLogStock<(d.ebonyLogCost or 0) then return false,"Premalo ebenovih hlodov" end; if d.goldCost and Sawmill.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and Sawmill.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #Sawmill.buildings==0 then return false,"Potrebna delavnica" end; if not Sawmill.maker then return false,"Potreben žagar" end; return true end
function Sawmill.make(pt,qty) qty=qty or 10; local ok,e=Sawmill.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.pineLogCost then Sawmill.pineLogStock=Sawmill.pineLogStock-d.pineLogCost*qty end; if d.oakLogCost then Sawmill.oakLogStock=Sawmill.oakLogStock-d.oakLogCost*qty end; if d.ashLogCost then Sawmill.ashLogStock=Sawmill.ashLogStock-d.ashLogCost*qty end; if d.yewLogCost then Sawmill.yewLogStock=Sawmill.yewLogStock-d.yewLogCost*qty end; if d.ebonyLogCost then Sawmill.ebonyLogStock=Sawmill.ebonyLogStock-d.ebonyLogCost*qty end; if d.goldCost then Sawmill.goldStock=Sawmill.goldStock-d.goldCost*qty end; if d.jewelCost then Sawmill.jewelStock=Sawmill.jewelStock-d.jewelCost*qty end; local t=d.time; if Sawmill.maker then t=math.max(1,t-math.floor(Sawmill.maker.skill/12)) end; table.insert(Sawmill.activeMaking,{id="sawmill_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,quality=d.quality or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function Sawmill.completeMaking(m) local q=1.0+(Sawmill.getQualityBonus()/100); if Sawmill.maker then q=q+(Sawmill.maker.skill/180) end; q=math.min(2.0,q); Sawmill.productStock[m.productType]=(Sawmill.productStock[m.productType] or 0)+m.quantity; Sawmill.totalProducts=Sawmill.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if Sawmill.maker then Sawmill.maker.itemsMade=Sawmill.maker.itemsMade+m.quantity; if math.random()<0.20 then Sawmill.maker.skill=math.min(100,Sawmill.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Deska izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sawmill.completed",{productName=m.productName,quality=m.quality}) end end
function Sawmill.update(dt) if not _G.state then return end; Sawmill.dayTimer=Sawmill.dayTimer+dt; if Sawmill.dayTimer>=30 then Sawmill.dayTimer=0; for i=#Sawmill.activeMaking,1,-1 do local m=Sawmill.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then Sawmill.completeMaking(m); table.remove(Sawmill.activeMaking,i) end end; local tu=0; for _,bd in ipairs(Sawmill.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if Sawmill.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function Sawmill.getStats() return {pineLogStock=Sawmill.pineLogStock,oakLogStock=Sawmill.oakLogStock,ashLogStock=Sawmill.ashLogStock,yewLogStock=Sawmill.yewLogStock,ebonyLogStock=Sawmill.ebonyLogStock,goldStock=Sawmill.goldStock,jewelStock=Sawmill.jewelStock,productStock=Sawmill.productStock,numBuildings=#Sawmill.buildings,hasMaker=Sawmill.maker~=nil,makerName=Sawmill.maker and Sawmill.maker.name or "—",makerSkill=Sawmill.maker and Sawmill.maker.skill or 0,activeMaking=#Sawmill.activeMaking,totalProducts=Sawmill.totalProducts} end
return Sawmill
